 1	/*
 2	https://leetcode.com/problems/two-sum/
 3	function twoSum(nums: number[], target: number): number[] {
 4	    const n = nums.length;
 5	    for(let i = 0; i < n; i++) {
 6	        for(let k = i+1; k < n; k++) {
 7	            if(nums[i] + nums[k] == target) return [i,k]; 
 8	        }
 9	    }
10	};
11	*/
12	predicate summingPair(i: nat, j: nat, nums: seq<int>, target: int)
13	    requires i < |nums|
14	    requires j < |nums|
15	{
16	    i != j &&  nums[i] + nums[j] == target
17	}
18	method twoSum(nums: seq<int>, target: int) returns (pair: (nat, nat))
19	    requires exists i:nat,j:nat :: i < j < |nums| && summingPair(i, j, nums, target) && forall l: nat, m: nat :: l <  m < |nums| && l != i && m != j ==> !summingPair(l, m, nums, target)
20	    ensures 0 <= pair.0 < |nums| && 0 <= pair.1 < (|nums|) - 1 && summingPair(pair.0, pair.1, nums, target)
21	{
22	    pair := (0,0);
23	    var i: nat := 0;
24	    while i < |nums| 
25	        invariant i <= |nums|
26	        invariant forall z: nat, j: nat :: 0 <= z < i  && z+1 <= j < |nums| ==> !summingPair(z, j, nums, target)
27	    {
28	        var k: nat := i + 1;
29	        while k < |nums| 
30	            invariant i + 1 <= k <= |nums|
31	            // invariant forall q: nat :: i+1 <= q < k < |nums| ==> !summingPair(i,q, nums, target) //this fails to verify
32	            invariant forall q: nat :: i+1 <= q < k <= |nums| ==> !summingPair(i,q, nums, target) //this verifies
33	        {
34	            // assert i < k < |nums|;
35	            if nums[i] + nums[k] == target {
36	                pair := (i,k);
37	                return pair;
38	            }
39	            k := k + 1;
40	        }
41	        i := i + 1;
42	    }
43	}

